SELECT ?id ?current_spec ?started_spec ?started_by ?started_at ?started_session ?acknowledged_spec ?ack_by ?ack_at ?acked_current WHERE {
  GRAPH <{graph}> {
    <{entity}> <https://schema.org/identifier> ?id .
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specVersion> ?current }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specStartVersion> ?started }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specStartActor> ?started_by }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specStartAt> ?started_at }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specStartSession> ?started_session }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specAckVersion> ?acked }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specAckActor> ?ack_by }
    OPTIONAL { <{entity}> <https://seeds.local/ontology/specAckAt> ?ack_at }
    OPTIONAL { <{entity}> <https://schema.org/agent> ?assignee }
  }
  BIND(COALESCE(STR(?current), "UNKNOWN") AS ?current_spec)
  BIND(COALESCE(STR(?started), "UNKNOWN") AS ?started_spec)
  BIND(COALESCE(STR(?acked), "UNKNOWN") AS ?acknowledged_spec)
  BIND(IF(BOUND(?current) && BOUND(?acked) && BOUND(?ack_by) && BOUND(?assignee),
          (?current = ?acked && ?ack_by = ?assignee), false) AS ?acked_current)
} LIMIT 2
